20	async function getToken(): Promise<string> {
21	  const session = await vscode.authentication.getSession(
22	    'github',
23	    ['repo', 'read:org', 'read:user', 'project'],
24	    { createIfNone: true }
25	  );
26	  return session.accessToken;
27	}
