79	// The big GraphQL query - works for both org and user
80	// Note: body is NOT fetched here (too large) — loaded on demand via fetchItemBody
81	const PROJECT_ITEMS_QUERY = `
82	query GetProjectItems($login: String!, $number: Int!, $isOrg: Boolean!, $cursor: String) {
83	  rateLimit { remaining limit resetAt }
84	  viewer { login }
85	  org: organization(login: $login) @include(if: $isOrg) {
86	    projectV2(number: $number) {
87	      title
88	      items(first: 100, after: $cursor) {
89	        pageInfo { hasNextPage endCursor }
90	        nodes {
91	          id
92	          type
93	          fieldValues(first: 20) {
94	            nodes {
95	              ... on ProjectV2ItemFieldSingleSelectValue {
96	                name
97	                field { ... on ProjectV2SingleSelectField { name } }
98	              }
99	              ... on ProjectV2ItemFieldIterationValue {
100	                title
101	                field { ... on ProjectV2IterationField { name } }
102	              }
103	            }
104	          }
105	          content {
106	            ... on Issue {
107	              __typename
108	              number title url state createdAt updatedAt
109	              author { login avatarUrl }
110	              assignees(first: 10) { nodes { login avatarUrl } }
111	              labels(first: 10) { nodes { name color } }
112	              milestone { title number dueOn }
113	              repository { name owner { login } }
114	            }
115	            ... on PullRequest {
116	              __typename
117	              number title url state isDraft createdAt updatedAt
118	              additions deletions headRefName
119	              author { login avatarUrl }
120	              assignees(first: 10) { nodes { login avatarUrl } }
121	              labels(first: 10) { nodes { name color } }
122	              milestone { title number dueOn }
123	              repository { name owner { login } }
124	              commits(last: 1) {
125	                nodes { commit { statusCheckRollup { state } } }
126	              }
127	              reviews(last: 5) {
128	                nodes { state author { login avatarUrl } }
129	              }
130	              reviewRequests(first: 10) {
131	                nodes { requestedReviewer { ... on User { login avatarUrl } } }
132	              }
133	              closingIssuesReferences(first: 10) {
134	                nodes { number }
135	              }
136	            }
137	          }
138	        }
139	      }
140	    }
141	  }
142	  user: user(login: $login) @skip(if: $isOrg) {
143	    projectV2(number: $number) {
144	      title
145	      items(first: 100, after: $cursor) {
146	        pageInfo { hasNextPage endCursor }
147	        nodes {
148	          id
149	          type
150	          fieldValues(first: 20) {
151	            nodes {
152	              ... on ProjectV2ItemFieldSingleSelectValue {
153	                name
154	                field { ... on ProjectV2SingleSelectField { name } }
155	              }
156	              ... on ProjectV2ItemFieldIterationValue {
157	                title
158	                field { ... on ProjectV2IterationField { name } }
159	              }
160	            }
161	          }
162	          content {
163	            ... on Issue {
164	              __typename
165	              number title url state createdAt updatedAt
166	              author { login avatarUrl }
167	              assignees(first: 10) { nodes { login avatarUrl } }
168	              labels(first: 10) { nodes { name color } }
169	              milestone { title number dueOn }
170	              repository { name owner { login } }
171	            }
172	            ... on PullRequest {
173	              __typename
174	              number title url state isDraft createdAt updatedAt
175	              additions deletions headRefName
176	              author { login avatarUrl }
177	              assignees(first: 10) { nodes { login avatarUrl } }
178	              labels(first: 10) { nodes { name color } }
179	              milestone { title number dueOn }
180	              repository { name owner { login } }
181	              commits(last: 1) {
182	                nodes { commit { statusCheckRollup { state } } }
183	              }
184	              reviews(last: 5) {
185	                nodes { state author { login avatarUrl } }
186	              }
187	              reviewRequests(first: 10) {
188	                nodes { requestedReviewer { ... on User { login avatarUrl } } }
189	              }
190	              closingIssuesReferences(first: 10) {
191	                nodes { number }
192	              }
193	            }
194	          }
