273	function extractColumn(node: RawProjectNode, statusFieldName: string): string {
274	  const nodes = node.fieldValues?.nodes ?? [];
275	  for (const fv of nodes) {
276	    if (fv.field?.name === statusFieldName && fv.name) {
277	      return fv.name;
278	    }
279	  }
280	  return 'Uncategorized';
281	}
282	
283	function extractSprint(node: RawProjectNode): { sprint: string; sprintField: string } | undefined {
284	  for (const fv of node.fieldValues?.nodes ?? []) {
285	    if (fv.title !== undefined && fv.field?.name) {
286	      return { sprint: fv.title, sprintField: fv.field.name };
287	    }
288	  }
289	  return undefined;
290	}
291	
292	function extractLatestReviews(rawReviews: { nodes: Array<{ state: string; author: GHUser }> } | null | undefined): ReviewInfo[] {
293	  const byReviewer = new Map<string, ReviewInfo>();
294	  for (const r of rawReviews?.nodes ?? []) {
295	    if (r?.author) {
296	      byReviewer.set(r.author.login, { state: r.state as ReviewInfo['state'], author: r.author });
297	    }
298	  }
299	  return Array.from(byReviewer.values());
300	}
