302	function parseItem(node: RawProjectNode, column: string): BoardItem | null {
303	  // Skip null content and Draft Issues (type: DraftIssue) — they lack standard fields
304	  if (!node.content || !('__typename' in node.content) || (node.content.__typename !== 'Issue' && node.content.__typename !== 'PullRequest')) {
305	    return null;
306	  }
307	  const c = node.content as RawIssue | RawPR;
308	
309	  const base = {
310	    id: node.id,
311	    column,
312	    author: c.author ?? { login: 'unknown', avatarUrl: '' },
313	    assignees: c.assignees?.nodes ?? [],
314	    labels: c.labels?.nodes ?? [],
315	    repository: c.repository?.name ?? '',
316	    repositoryOwner: c.repository?.owner?.login ?? '',
317	    createdAt: c.createdAt,
318	    updatedAt: c.updatedAt,
319	    body: undefined, // loaded on demand via fetchBody
320	    milestone: c.milestone
321	      ? { title: c.milestone.title, number: c.milestone.number, dueOn: c.milestone.dueOn }
322	      : undefined,
323	    ...(() => {
324	      const s = extractSprint(node);
325	      return s ? { sprint: s.sprint, sprintField: s.sprintField } : {};
326	    })(),
327	  };
328	
329	  if (c.__typename === 'Issue') {
330	    return {
331	      ...base,
332	      number: c.number,
333	      title: c.title,
334	      type: 'ISSUE',
335	      url: c.url,
336	      state: c.state,
337	    };
338	  }
339	
340	  if (c.__typename === 'PullRequest') {
341	    const pr = c as RawPR;
342	    const ciRaw = pr.commits?.nodes?.[0]?.commit?.statusCheckRollup?.state ?? 'none';
343	    return {
344	      ...base,
345	      number: pr.number,
346	      title: pr.title,
347	      type: 'PULL_REQUEST',
348	      url: pr.url,
349	      state: pr.state,
350	      isDraft: pr.isDraft,
351	      additions: pr.additions,
352	      deletions: pr.deletions,
353	      headRefName: pr.headRefName,
354	      ciState: ciRaw as CIState,
355	      reviews: extractLatestReviews(pr.reviews),
356	      reviewRequests: (pr.reviewRequests?.nodes ?? [])
357	        .map((r) => r.requestedReviewer)
358	        .filter((r): r is GHUser => r !== null),
359	      closingIssueNumbers: (pr.closingIssuesReferences?.nodes ?? []).map((n) => n.number),
360	    };
361	  }
362	
363	  return null;
364	}
