366	interface RawRepoPR {
367	  number: number;
368	  title: string;
369	  url: string;
370	  state: string;
371	  isDraft: boolean;
372	  createdAt: string;
373	  updatedAt: string;
374	  additions: number;
375	  deletions: number;
376	  headRefName: string;
377	  author: GHUser | null;
378	  assignees: { nodes: GHUser[] } | null;
379	  repository: { name: string; owner: { login: string } } | null;
380	  commits: { nodes: Array<{ commit: { statusCheckRollup: { state: string } | null } }> } | null;
381	  reviews: { nodes: Array<{ state: string; author: GHUser }> } | null;
382	  reviewRequests: { nodes: Array<{ requestedReviewer: GHUser | null }> } | null;
383	  closingIssuesReferences: { nodes: Array<{ number: number }> } | null;
384	}
