386	/**
387	 * For each repo that has board issues, fetch all open PRs and return those
388	 * that close (via `Fixes #N`, `Closes #N`, etc.) a board issue.
389	 * The linked PR inherits the parent issue's column and sprint.
390	 */
391	async function fetchLinkedPRsFromRepos(
392	  token: string,
393	  issueByRepo: Map<string, Map<number, BoardItem>>,
394	  groups: Record<string, BoardItem[]>
395	): Promise<BoardItem[]> {
396	  const linkedPRMap = new Map<string, BoardItem>(); // `owner/repo#number` → BoardItem
397	  // Track PR numbers already on the board to avoid duplicates
398	  const boardPRKeys = new Set<string>();
399	  for (const items of Object.values(groups)) {
400	    for (const item of items) {
401	      if (item.type === 'PULL_REQUEST') {
402	        boardPRKeys.add(`${item.repositoryOwner}/${item.repository}#${item.number}`);
403	      }
404	    }
405	  }
406	
407	  await Promise.all(
408	    Array.from(issueByRepo.entries()).map(async ([repoKey, issueMap]) => {
409	      const [repoOwner, repoName] = repoKey.split('/');
410	      let prCursor: string | null = null;
411	
412	      do {
413	        let repoData: { repository: { pullRequests: { pageInfo: { hasNextPage: boolean; endCursor: string | null }; nodes: RawRepoPR[] } } } | null = null;
414	        try {
415	          repoData = await graphql<{ repository: { pullRequests: { pageInfo: { hasNextPage: boolean; endCursor: string | null }; nodes: RawRepoPR[] } } }>(
416	            token,
417	            REPO_OPEN_PRS_QUERY,
418	            { owner: repoOwner, repo: repoName, cursor: prCursor }
419	          );
420	        } catch {
421	          break; // skip repos we can't access
422	        }
423	
424	        const prs = repoData?.repository?.pullRequests?.nodes ?? [];
425	        for (const rawPR of prs) {
426	          const prKey = `${repoOwner}/${repoName}#${rawPR.number}`;
427	          if (boardPRKeys.has(prKey) || linkedPRMap.has(prKey)) continue;
428	
429	          // Check if this PR closes any of our board issues
430	          const closingNums = rawPR.closingIssuesReferences?.nodes?.map((n) => n.number) ?? [];
431	          const parentIssue = closingNums.map((n) => issueMap.get(n)).find((i) => i !== undefined);
432	          if (!parentIssue) continue;
433	
434	          const ciRaw = rawPR.commits?.nodes?.[0]?.commit?.statusCheckRollup?.state ?? 'none';
435	          linkedPRMap.set(prKey, {
436	            id: `linked-${prKey}`,
437	            number: rawPR.number,
438	            title: rawPR.title,
439	            type: 'PULL_REQUEST',
440	            url: rawPR.url,
441	            column: parentIssue.column,
442	            state: rawPR.state,
443	            author: rawPR.author ?? { login: 'unknown', avatarUrl: '' },
444	            assignees: rawPR.assignees?.nodes ?? [],
445	            labels: parentIssue.labels,
446	            repository: repoName,
447	            repositoryOwner: repoOwner,
448	            createdAt: rawPR.createdAt,
449	            updatedAt: rawPR.updatedAt,
450	            isDraft: rawPR.isDraft,
451	            additions: rawPR.additions,
452	            deletions: rawPR.deletions,
453	            headRefName: rawPR.headRefName,
454	            ciState: ciRaw as CIState,
455	            reviews: extractLatestReviews(rawPR.reviews),
456	            reviewRequests: (rawPR.reviewRequests?.nodes ?? [])
457	              .map((r) => r.requestedReviewer)
458	              .filter((r): r is GHUser => r !== null),
459	            sprint: parentIssue.sprint,
460	            sprintField: parentIssue.sprintField,
461	          });
462	        }
463	
464	        if (repoData?.repository?.pullRequests?.pageInfo?.hasNextPage) {
465	          prCursor = repoData.repository.pullRequests.pageInfo.endCursor;
466	        } else {
467	          prCursor = null;
468	        }
469	      } while (prCursor !== null);
470	    })
471	  );
472	
473	  return Array.from(linkedPRMap.values());
474	}
