476	export async function fetchProjectData(
477	  owner: string,
478	  projectNumber: number,
479	  isOrg: boolean,
480	  statusFieldName: string
481	): Promise<RunwayData> {
482	  const token = await getToken();
483	  const allNodes: RawProjectNode[] = [];
484	  let projectTitle = '';
485	  let viewerLogin = '';
486	  let cursor: string | null = null;
487	
488	  type ProjectResponse = {
489	    rateLimit?: RateLimit;
490	    viewer: { login: string };
491	    org?: { projectV2: ProjectData };
492	    user?: { projectV2: ProjectData };
493	  };
494	  let lastRateLimit: RateLimit | undefined;
495	
496	  do {
497	    const data: ProjectResponse = await graphql<ProjectResponse>(
498	      token,
499	      PROJECT_ITEMS_QUERY,
500	      { login: owner, number: projectNumber, isOrg, cursor }
501	    );
502	
503	    if (data.rateLimit) lastRateLimit = data.rateLimit;
504	    if (!viewerLogin) viewerLogin = data.viewer?.login ?? '';
505	
506	    const project: ProjectData | undefined = isOrg ? data.org?.projectV2 : data.user?.projectV2;
507	    if (!project) {
508	      throw new Error(`Project #${projectNumber} not found for ${owner}`);
509	    }
510	
511	    projectTitle = project.title;
512	    allNodes.push(...project.items.nodes);
513	
514	    if (project.items.pageInfo.hasNextPage) {
515	      cursor = project.items.pageInfo.endCursor;
516	    } else {
517	      cursor = null;
518	    }
519	  } while (cursor !== null);
520	
521	  // Group items by column; also build a map of issue number -> BoardItem for linking
522	  const groups: Record<string, BoardItem[]> = {};
523	  const sprintsSet = new Set<string>();
524	  // key: `${owner}/${repo}` -> Map<issueNumber, BoardItem>
525	  const issueByRepo = new Map<string, Map<number, BoardItem>>();
526	
527	  for (const node of allNodes) {
528	    const column = extractColumn(node, statusFieldName);
529	    const item = parseItem(node, column);
530	    if (!item) continue;
531	
532	    if (!groups[column]) {
533	      groups[column] = [];
534	    }
535	    groups[column].push(item);
536	    if (item.sprint) sprintsSet.add(item.sprint);
537	
538	    // Track board issues by repo for later PR linking
539	    if (item.type === 'ISSUE' && item.repositoryOwner && item.repository) {
540	      const repoKey = `${item.repositoryOwner}/${item.repository}`;
541	      if (!issueByRepo.has(repoKey)) issueByRepo.set(repoKey, new Map());
542	      issueByRepo.get(repoKey)!.set(item.number, item);
543	    }
544	  }
545	
546	  // Build ordered column list — case-insensitive so "Ready for review" matches "Ready For Review"
547	  const colOrderLower = COLUMN_ORDER.map((c) => c.toLowerCase());
548	  const knownPresent = Object.keys(groups)
549	    .filter((c) => colOrderLower.includes(c.toLowerCase()))
550	    .sort((a, b) => colOrderLower.indexOf(a.toLowerCase()) - colOrderLower.indexOf(b.toLowerCase()));
551	  const extras = Object.keys(groups).filter((c) => !colOrderLower.includes(c.toLowerCase()));
552	  const columns = [...knownPresent, ...extras];
553	
554	  const totalCount = Object.values(groups).reduce((sum, items) => sum + items.length, 0);
555	  // Natural sort descending (Sprint 21 first, Sprint 1 last)
556	  const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
557	  const sprints = Array.from(sprintsSet).sort((a, b) => collator.compare(b, a));
558	
559	  // Fetch open PRs from each repo that has board issues, match by closingIssuesReferences
560	  const linkedIssuePRs = await fetchLinkedPRsFromRepos(token, issueByRepo, groups);
561	
562	  return {
563	    projectTitle,
564	    columns,
565	    groups,
566	    sprints,
567	    lastUpdated: new Date().toISOString(),
568	    totalCount,
569	    viewerLogin,
570	    linkedIssuePRs,
571	    rateLimit: lastRateLimit,
572	  };
573	}
574	
575	// Step 1: get linked PRs via closing references + timeline cross-references
576	const LINKED_PRS_QUERY = `
577	query GetLinkedPRs($owner: String!, $repo: String!, $number: Int!) {
578	  repository(owner: $owner, name: $repo) {
579	    issue(number: $number) {
580	      closingPullRequests(first: 10) {
581	        nodes {
582	          number title url state isDraft headRefName
583	          commits(last: 1) { nodes { commit { oid } } }
584	        }
585	      }
586	      timelineItems(first: 25, itemTypes: [CROSS_REFERENCED_EVENT]) {
587	        nodes {
588	          ... on CrossReferencedEvent {
589	            source {
590	              ... on PullRequest {
591	                number title url state isDraft headRefName
592	                commits(last: 1) { nodes { commit { oid } } }
593	              }
594	            }
595	          }
596	        }
597	      }
598	    }
599	  }
600	}
601	`;
602	
603	interface RawLinkedPR {
604	  number: number;
605	  title: string;
606	  url: string;
607	  state: string;
608	  isDraft: boolean;
609	  headRefName: string;
610	  commits: { nodes: Array<{ commit: { oid: string } }> } | null;
611	}
612	
613	interface RawCheckRunResponse {
614	  check_runs: Array<{
615	    name: string;
616	    status: string;
617	    conclusion: string | null;
618	    details_url: string | null;
619	    html_url: string;
620	  }>;
621	  total_count: number;
622	}
623	
624	async function fetchCheckRunsForCommit(token: string, owner: string, repo: string, sha: string): Promise<CheckRun[]> {
625	  const url = `https://api.github.com/repos/${owner}/${repo}/commits/${sha}/check-runs?per_page=50`;
626	  const resp = await fetch(url, {
627	    headers: {
628	      Authorization: `bearer ${token}`,
629	      Accept: 'application/vnd.github+json',
630	    },
631	  });
632	  if (!resp.ok) return [];
633	  const json = (await resp.json()) as RawCheckRunResponse;
634	  return (json.check_runs ?? []).map((r) => ({
635	    name: r.name,
636	    status: r.status.toUpperCase(),
