642	export async function fetchLinkedPRChecks(
643	  owner: string,
644	  repo: string,
645	  issueNumber: number
646	): Promise<LinkedPR[]> {
647	  const token = await getToken();
648	  const data = await graphql<{
649	    repository: {
650	      issue: {
651	        closingPullRequests: { nodes: RawLinkedPR[] };
652	        timelineItems: { nodes: Array<{ source?: RawLinkedPR }> };
653	      } | null;
654	    } | null;
655	  }>(token, LINKED_PRS_QUERY, { owner, repo, number: issueNumber });
656	
657	  // Merge closing PRs + timeline cross-references, deduplicate by number
658	  const closing = data.repository?.issue?.closingPullRequests?.nodes ?? [];
659	  const crossRefs = (data.repository?.issue?.timelineItems?.nodes ?? [])
660	    .map((n) => n.source)
661	    .filter((s): s is RawLinkedPR => !!s && 'number' in s);
662	
663	  const seen = new Set<number>();
664	  const merged: RawLinkedPR[] = [];
665	  for (const pr of [...closing, ...crossRefs]) {
666	    if (!seen.has(pr.number)) {
667	      seen.add(pr.number);
668	      merged.push(pr);
669	    }
670	  }
671	
672	  if (!merged.length) return [];
673	
674	  // Fetch check runs for each PR in parallel
675	  const results = await Promise.all(
676	    merged.map(async (pr): Promise<LinkedPR> => {
677	      const sha = pr.commits?.nodes?.[0]?.commit?.oid;
678	      const checkRuns = sha ? await fetchCheckRunsForCommit(token, owner, repo, sha) : [];
679	
680	      // Derive overall CI state from check runs
681	      let ciState: CIState = 'none';
682	      if (checkRuns.length) {
683	        if (checkRuns.some((r) => r.status !== 'COMPLETED')) ciState = 'PENDING';
684	        else if (checkRuns.some((r) => r.conclusion === 'FAILURE' || r.conclusion === 'TIMED_OUT')) ciState = 'FAILURE';
685	        else if (checkRuns.every((r) => r.conclusion === 'SUCCESS' || r.conclusion === 'SKIPPED' || r.conclusion === 'NEUTRAL')) ciState = 'SUCCESS';
686	        else ciState = 'PENDING';
687	      }
688	
689	      return {
690	        number: pr.number,
691	        title: pr.title,
692	        url: pr.url,
693	        state: pr.state,
694	        isDraft: pr.isDraft,
695	        headRefName: pr.headRefName,
696	        ciState,
697	        checkRuns,
698	      };
699	    })
700	  );
701	
702	  return results;
703	}
