798	export async function generateStandupData(viewerLogin: string): Promise<{ data: StandupData; markdown: string }> {
799	  const token = await getToken();
800	  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().split('T')[0];
801	  const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
802	
803	  const repoFromUrl = (url: string) => url.replace('https://api.github.com/repos/', '');
804	
805	  async function search(q: string): Promise<RawSearchIssue[]> {
806	    const resp = await fetch(`https://api.github.com/search/issues?q=${encodeURIComponent(q)}&per_page=30`, {
807	      headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' },
808	    });
809	    if (!resp.ok) return [];
810	    const json = (await resp.json()) as { items: RawSearchIssue[] };
811	    return json.items ?? [];
812	  }
813	
814	  async function fetchCommentedItems(): Promise<RawSearchIssue[]> {
815	    const resp = await fetch(
816	      `https://api.github.com/users/${viewerLogin}/events?per_page=100`,
817	      { headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' } }
818	    );
819	    if (!resp.ok) return [];
820	    const events = (await resp.json()) as RawGitHubEvent[];
821	
822	    const seenUrls = new Set<string>();
823	    const items: RawSearchIssue[] = [];
824	
825	    for (const event of events) {
826	      // Events are newest-first — stop once we're past the 24h window
827	      if (event.created_at < yesterday) break;
828	
829	      const isMyComment =
830	        (event.type === 'IssueCommentEvent' && event.payload.action === 'created') ||
831	        (event.type === 'PullRequestReviewCommentEvent' && event.payload.action === 'created') ||
832	        event.type === 'PullRequestReviewEvent';
833	      if (!isMyComment) continue;
834	
835	      const target = event.payload.issue ?? event.payload.pull_request;
836	      if (!target || seenUrls.has(target.html_url)) continue;
837	      seenUrls.add(target.html_url);
838	
839	      items.push({
840	        number: target.number,
841	        title: target.title,
842	        html_url: target.html_url,
843	        repository_url: `https://api.github.com/repos/${event.repo.name}`,
844	        pull_request: (event.payload.pull_request ?? event.payload.issue?.pull_request) ? { merged_at: null } : undefined,
845	      });
846	    }
847	    return items;
848	  }
849	
850	  const [mergedPRs, openPRs, commentedItems] = await Promise.all([
851	    search(`is:pr is:merged author:${viewerLogin} merged:>${yesterday}`),
852	    search(`is:pr is:open author:${viewerLogin} updated:>${yesterday}`),
853	    fetchCommentedItems(),
854	  ]);
855	
856	  // Remove items already listed in merged/open from the commented section
857	  const listedUrls = new Set([...mergedPRs, ...openPRs].map((i) => i.html_url));
858	  const uniqueCommented = commentedItems.filter((i) => !listedUrls.has(i.html_url));
859	
860	  function toRepoGroups(items: RawSearchIssue[]): StandupRepoGroup[] {
861	    const map = new Map<string, StandupRepoGroup['items']>();
862	    for (const item of items) {
863	      const repo = repoFromUrl(item.repository_url);
864	      if (!map.has(repo)) map.set(repo, []);
865	      map.get(repo)!.push({ number: item.number, title: item.title, url: item.html_url, isPR: !!item.pull_request });
866	    }
867	    return Array.from(map.entries()).map(([repo, its]) => ({ repo, items: its }));
868	  }
869	
870	  const rawSections: Array<{ key: string; icon: string; title: string; items: RawSearchIssue[] }> = [
871	    { key: 'merged',    icon: '✅', title: 'Merged PRs',    items: mergedPRs },
872	    { key: 'open',      icon: '🔄', title: 'Open PRs',      items: openPRs },
873	    { key: 'commented', icon: '💬', title: 'Commented on',  items: uniqueCommented },
874	  ];
875	
876	  const sections: StandupSection[] = rawSections
877	    .filter((s) => s.items.length > 0)
878	    .map((s) => ({ key: s.key, icon: s.icon, title: s.title, groups: toRepoGroups(s.items) }));
879	
880	  const data: StandupData = { date: today, sections };
881	
882	  // Generate markdown from structured data (used for the copy-as-markdown button)
883	  const lines: string[] = [`## Daily Standup — ${today}`, ''];
884	  if (sections.length === 0) {
885	    lines.push('*No activity found in the last 24 hours.*', '');
886	  } else {
887	    for (const section of sections) {
888	      lines.push(`### ${section.icon} ${section.title}`);
889	      for (const group of section.groups) {
890	        lines.push(`**${group.repo}**`);
891	        for (const item of group.items) {
892	          lines.push(`- [#${item.number} ${item.title}](${item.url})`);
893	        }
894	      }
895	      lines.push('');
896	    }
897	  }
898	  lines.push('*Generated by SprintHub*');
899	
900	  return { data, markdown: lines.join('\n') };
901	}
