1003	    if (json.encoding === 'base64' && json.content) {
1004	      return atob(json.content.replace(/\n/g, ''));
1005	    }
1006	    return null;
1007	  }
1008	
1009	  const content =
1010	    (await tryPath('.github/CODEOWNERS')) ??
1011	    (await tryPath('CODEOWNERS')) ??
1012	    (await tryPath('docs/CODEOWNERS'));
