105	            break;
106	          // Phase 1: File-Level Deep Linking
107	          case 'fetchPRFiles':
108	            void this._fetchPRFiles(message.prKey, message.owner, message.repo, message.prNumber);
109	            break;
110	          case 'openPRFile':
111	            void this._openPRFile(message.owner, message.repo, message.prNumber, message.filename, message.patch);
112	            break;
113	          // Phase 3: Standup Generator
114	          case 'generateStandup':
115	            void this._generateStandup(message.viewerLogin);
116	            break;
117	          // Phase 3: Metadata Sync
118	          case 'updateMetadata':
119	            void this._updateMetadata(message.itemId, message.owner, message.repo, message.issueNumber, message.labels, message.assignees);
120	            break;
121	          case 'fetchRepoLabels':
122	            void this._fetchRepoLabels(message.owner, message.repo);
123	            break;
124	          case 'convertDraftToReady':
125	            void this._convertDraftToReady(message.itemId, message.owner, message.repo, message.prNumber);
126	            break;
127	          case 'mergePR':
128	            void this._mergePR(message.itemId, message.owner, message.repo, message.prNumber, message.mergeMethod);
129	            break;
130	          case 'fetchCodeowners':
131	            void this._fetchCodeowners(message.owner, message.repo);
132	            break;
133	          case 'fetchSettingsOwners':
134	            void this._fetchSettingsOwners();
135	            break;
136	          case 'fetchSettingsProjects':
137	            void this._fetchSettingsProjects(message.owner, message.ownerType);
138	            break;
139	        }
140	      },
141	      null,
142	      this._disposables
143	    );
144	
145	    vscode.workspace.onDidChangeConfiguration(
146	      (e) => {
147	        if (e.affectsConfiguration('sprinthub')) {
148	          this._sendConfig();
149	          // Only reload data when a field that affects the API query changes.
150	          // Cosmetic fields (liquidGlass, theme, colorBlind) and refreshInterval
151	          // must not trigger a full board re-fetch.
152	          const dataFields = ['owner', 'projectNumber', 'ownerType', 'statusFieldName'];
153	          if (dataFields.some((f) => e.affectsConfiguration(`sprinthub.${f}`))) {
154	            this._loadData();
155	          }
156	          this._scheduleRefresh();
157	        }
158	      },
159	      null,
160	      this._disposables
161	    );
162	
163	    this._loadData();
164	    this._sendConfig();
165	    this._scheduleRefresh();
166	  }
