270	  // ─── Phase 1: Work-On-This Engine ──────────────────────────────────────────
271	
272	  private async _workOnThis(branchName: string, _owner: string, _repo: string) {
273	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
274	    if (!cwd) {
275	      vscode.window.showErrorMessage('SprintHub: No workspace folder open to checkout branch.');
276	      return;
277	    }
278	
279	    let branchExists = false;
280	    try {
281	      await exec(`git rev-parse --verify "${branchName}"`, { cwd });
282	      branchExists = true;
283	    } catch {
284	      branchExists = false;
285	    }
286	
287	    let terminal = vscode.window.terminals.find((t) => t.name === 'SprintHub');
288	    if (!terminal) {
289	      terminal = vscode.window.createTerminal('SprintHub');
290	    }
291	    terminal.show(true);
292	
293	    if (branchExists) {
294	      terminal.sendText(`git checkout ${branchName}`);
295	    } else {
296	      terminal.sendText(`git fetch origin ${branchName} 2>/dev/null; git checkout -b ${branchName} origin/${branchName} 2>/dev/null || git checkout ${branchName}`);
297	    }
298	
299	    // Focus the most recently modified file in the workspace
300	    setTimeout(() => void this._focusMostRecentFile(cwd), 2000);
301	  }
