303	  private async _focusMostRecentFile(cwd: string) {
304	    try {
305	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
306	      const files = stdout.trim().split('\n').filter(Boolean);
307	      if (!files.length) return;
308	      const found = await vscode.workspace.findFiles(files[0], '**/node_modules/**', 1);
309	      if (found.length) {
310	        const doc = await vscode.workspace.openTextDocument(found[0]);
311	        await vscode.window.showTextDocument(doc, { preserveFocus: false });
312	      }
313	    } catch {
314	      // silently skip if git diff fails (detached HEAD, etc.)
315	    }
316	  }
