329	  private async _openPRFile(owner: string, repo: string, _prNumber: number, filename: string, patch?: string) {
330	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
331	    if (!cwd) {
332	      vscode.window.showWarningMessage('SprintHub: No workspace folder open.');
333	      return;
334	    }
335	
336	    const found = await vscode.workspace.findFiles(filename, '**/node_modules/**', 1);
337	    if (!found.length) {
338	      vscode.window.showWarningMessage(`SprintHub: File not found locally: ${filename}`);
339	      return;
340	    }
341	
342	    const doc = await vscode.workspace.openTextDocument(found[0]);
343	    let line = 0;
344	    if (patch) {
345	      const match = patch.match(/@@ -\d+(?:,\d+)? \+(\d+)/);
346	      if (match) line = Math.max(0, parseInt(match[1], 10) - 1);
347	    }
348	    const selection = new vscode.Range(line, 0, line, 0);
349	    await vscode.window.showTextDocument(doc, { selection });
350	  }
