352	  // ─── Phase 2: Hotspot Conflict Monitor ─────────────────────────────────────
353	
354	  private async _checkConflicts(data: RunwayData) {
355	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
356	    if (!cwd) return;
357	
358	    let localDirty: Set<string>;
359	    try {
360	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
361	      localDirty = new Set(stdout.trim().split('\n').filter(Boolean));
362	    } catch {
363	      return;
364	    }
365	
366	    if (!localDirty.size) {
367	      this._post({ type: 'conflictThreats', threats: [] });
368	      return;
369	    }
370	
371	    // Collect open PRs from board + linked PRs
372	    const openPRs: Array<{ owner: string; repo: string; number: number; title: string; author: string; url: string }> = [];
373	    const allBoardItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
374	    for (const item of allBoardItems) {
375	      if (item.type === 'PULL_REQUEST' && item.state === 'OPEN' && item.repositoryOwner && item.repository) {
376	        openPRs.push({
377	          owner: item.repositoryOwner,
378	          repo: item.repository,
379	          number: item.number,
380	          title: item.title,
381	          author: item.author.login,
382	          url: item.url,
383	        });
384	      }
385	    }
386	
387	    if (!openPRs.length) {
388	      this._post({ type: 'conflictThreats', threats: [] });
389	      return;
390	    }
391	
392	    try {
393	      const prFilesMap = await fetchAllOpenPRFiles(openPRs.map((p) => ({ owner: p.owner, repo: p.repo, number: p.number })));
394	      const threats: ConflictThreat[] = [];
395	
396	      for (const pr of openPRs) {
397	        const key = `${pr.owner}/${pr.repo}#${pr.number}`;
398	        const files = prFilesMap.get(key) ?? [];
399	        for (const file of files) {
400	          if (localDirty.has(file.filename)) {
401	            threats.push({
402	              filename: file.filename,
403	              prNumber: pr.number,
404	              prTitle: pr.title,
405	              prAuthor: pr.author,
406	              prUrl: pr.url,
407	            });
408	          }
409	        }
410	      }
411	
412	      this._post({ type: 'conflictThreats', threats });
413	    } catch {
414	      // conflict check is best-effort
415	    }
416	  }
