418	  // ─── Phase 2: Status Bar Blocker Watchdog ──────────────────────────────────
419	
420	  private _updateStatusBar(data: RunwayData) {
421	    const allItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
422	    const openPRs = allItems.filter((i) => i.type === 'PULL_REQUEST' && i.state === 'OPEN');
423	
424	    const ciFailures = openPRs.filter((i) => i.ciState === 'FAILURE' || i.ciState === 'ERROR');
425	    const changesRequested = openPRs.filter((i) =>
426	      i.reviews?.some((r) => r.state === 'CHANGES_REQUESTED')
427	    );
428	
429	    const total = ciFailures.length + changesRequested.length;
430	
431	    if (total === 0) {
432	      this._statusBarItem.text = '$(check) SprintHub';
433	      this._statusBarItem.backgroundColor = undefined;
434	    } else {
435	      const parts: string[] = [];
436	      if (ciFailures.length) parts.push(`${ciFailures.length} CI fail${ciFailures.length > 1 ? 's' : ''}`);
437	      if (changesRequested.length) parts.push(`${changesRequested.length} changes req`);
438	      this._statusBarItem.text = `$(warning) ${parts.join(' · ')}`;
439	      this._statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
440	    }
441	
442	    this._statusBarItem.show();
443	
444	    // Store for use in showBlockers quick-pick
445	    (this as unknown as Record<string, unknown>)._blockerPRs = { ciFailures, changesRequested };
446	  }
447	
448	  public showBlockersQuickPick() {
449	    const stored = (this as unknown as Record<string, unknown>)._blockerPRs as
450	      | { ciFailures: BoardItem[]; changesRequested: BoardItem[] }
451	      | undefined;
452	    if (!stored) {
453	      vscode.window.showInformationMessage('SprintHub: No blocker data loaded yet.');
454	      return;
455	    }
456	
457	    const { ciFailures, changesRequested } = stored;
458	    const items: vscode.QuickPickItem[] = [];
459	
460	    if (ciFailures.length) {
461	      items.push({ label: '$(error) CI Failing', kind: vscode.QuickPickItemKind.Separator });
462	      for (const pr of ciFailures) {
463	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
464	      }
465	    }
466	
467	    if (changesRequested.length) {
468	      items.push({ label: '$(git-pull-request) Changes Requested', kind: vscode.QuickPickItemKind.Separator });
469	      for (const pr of changesRequested) {
470	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
471	      }
472	    }
473	
474	    if (!items.length) {
475	      vscode.window.showInformationMessage('SprintHub: All PRs are healthy!');
476	      return;
477	    }
478	
479	    void vscode.window.showQuickPick(items, { title: 'SprintHub Blockers', placeHolder: 'Select a PR to open on GitHub' }).then((selected) => {
480	      if (selected?.detail) {
481	        void vscode.env.openExternal(vscode.Uri.parse(selected.detail));
482	      }
483	    });
484	  }
